public int RemoveDuplicatesCount(int[] nums)
{
    int write = 0;
    int i = 0;

    while (i < nums.Length)
    {
        int j = i;
        while (j < nums.Length && nums[j] == nums[i]) j++;

        int runLength = j - i;
        int keep = Math.Min(runLength, 2);

        for (int t = 0; t < keep; t++)
        {
            nums[write++] = nums[i];
        }

        i = j;
    }

    return write;
}

public int RemoveDuplicates(int[] nums)
{
    // slow is the next write position; the first two elements are always kept
    int slow = 0;

    foreach (int value in nums)
    {
        // Keep the value if fewer than two copies have been written
        if (slow < 2 || value != nums[slow - 2])
        {
            nums[slow] = value;
            slow++;
        }
    }

    return slow;
}

